import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

// 준비 코드: 환경 하나는 이름→값 표와 바깥 환경(parent)을 가져요. 블록 { }마다 새 환경이 생겨요.
static class Env {
    final Map<String, Integer> vars = new HashMap<>();
    final Env parent;
    Env(Env parent) { this.parent = parent; }
    // 이 이름을 정의한 가장 가까운 환경을 찾아요. 없으면 오류예요.
    Env find(String name) {
        for (Env e = this; e != null; e = e.parent) if (e.vars.containsKey(name)) return e;
        throw new IllegalStateException("정의되지 않은 이름 " + name);
    }
    int lookup(String name) { return find(name).vars.get(name); }
}

// 준비 코드: 식은 숫자나 이름을 + 와 - 로 이은 것이에요. 예: count + 1
static int eval(List<String> tokens, Env env) {
    int value = term(tokens.get(0), env);
    for (int i = 1; i + 1 < tokens.size(); i += 2) {
        int right = term(tokens.get(i + 1), env);
        value = tokens.get(i).equals("+") ? value + right : value - right;
    }
    return value;
}
static int term(String token, Env env) {
    return token.matches("-?\\d+") ? Integer.parseInt(token) : env.lookup(token);
}

static String chain(Env env) {
    List<String> parts = new ArrayList<>();
    for (Env e = env; e != null; e = e.parent) parts.add(new java.util.TreeMap<>(e.vars).toString());
    return String.join(" ← ", parts);
}

void main() {
    Scanner in = new Scanner(System.in);
    Env root = new Env(null);
    Env env = root;
    int lineNo = 0;
    while (in.hasNextLine()) {
        String line = in.nextLine().trim();
        if (line.isEmpty()) continue;
        lineNo++;
        List<String> tokens = List.of(line.split("\\s+"));
        try {
            switch (tokens.get(0)) {
                case "{" -> env = new Env(env);
                case "}" -> env = env.parent;
                case "let" -> env.vars.put(tokens.get(1), eval(tokens.subList(3, tokens.size()), env));
                case "set" -> {
                    String name = tokens.get(1);
                    int value = eval(tokens.subList(3, tokens.size()), env);
                    // 고칠 곳: 지금은 현재 환경에 값을 넣어요.
                    env.vars.put(name, value);
                }
                case "print" -> System.out.println("출력 " + env.lookup(tokens.get(1)));
                default -> throw new IllegalStateException("모르는 문장 " + tokens.get(0));
            }
            System.out.println("줄 " + lineNo + " | 문장 " + line + " | 환경 " + chain(env));
        } catch (IllegalStateException e) {
            System.out.println("줄 " + lineNo + " | 문장 " + line + " | 오류 " + e.getMessage());
            return;
        }
    }
}

